def bfs_check_girth(adj, n, girth=7):
    for start in range(n):
        dist = [-1] * n
        dist[start] = 0
        parent = [-1] * n
        q = deque([start])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif v != parent[u]:
                    if dist[u] + dist[v] + 1 < girth:
                        return False
    return True

