import random

def check_girth(adj, n, g=7):
    for start in range(n):
        dist = [-1] * n
        dist[start] = 0
        par = [-1] * n
        q = deque([start])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    par[v] = u
                    q.append(v)
                elif v != par[u]:
                    cl = dist[u] + dist[v] + 1
                    if cl < g:
                        return False
    return True

def find_graph(seed=1):
    random.seed(seed)
    n = 25
    adj = [set() for _ in range(n)]
    # Base: two disjoint cycles would be bad, so one Hamilton cycle
    for i in range(n):
        adj[i].add((i+1)%n)
        adj[(i+1)%n].add(i)
    # Add random long distance edges
