            j = (i + k) % n
            candidates.append((i, j))
    random.shuffle(candidates)
    for u, v in candidates:
        if v in adj[u]: continue
        if len(adj[u]) >=5 or len(adj[v]) >=5: continue
        adj[u].add(v)
        adj[v].add(u)
